module Prob_8_38 (  output reg [7: 0] 	Sum,   output reg 			Car_Bor,			  input [7: 0] 			Data_A, Data_B);  reg [7: 0]				Reg_A, Reg_B;      always @ (Data_A, Data_B)           case ({Data_A[7], Data_B[7]})		            2'b00, 2'b11:			begin								// ++, --    			 				   {Car_Bor, Sum[6: 0]} = Data_A[6: 0] + Data_B[6: 0];              	  	   Sum[7] = Data_A[7];            		end                    default:				if (Data_A[6: 0] >= Data_B[6: 0]) begin				// +-, -+          {Car_Bor, Sum[6: 0]} = Data_A[6: 0] - Data_B[6: 0];          Sum[7] = Data_A[7];       end       else begin          {Car_Bor, Sum[6: 0]} = Data_B[6: 0] - Data_A[6: 0];          Sum[7] = Data_B[7];       end      endcaseendmodulemodule t_Prob_8_38 ();  wire [7: 0] 	Sum;  wire 			Car_Bor;  reg [7: 0] 	Data_A, Data_B;  wire [6: 0] 	Mag_A, Mag_B;  assign 		Mag_A = M0.Data_A[6: 0];			// Hierarchical dereferencing  assign 		Mag_B = M0.Data_B[6: 0];  wire 			Sign_A = M0.Data_A[7];  wire 			Sign_B = M0.Data_B[7];  wire 			Sign = Sum[7];  wire [7: 0] 	Mag = Sum[6: 0];  Prob_8_38 M0 (Sum, Car_Bor,  Data_A, Data_B);  initial #650 $finish;  
  initial fork      // Addition								//  A        B     #0 begin Data_A = {1'b0, 7'd25}; Data_B = {1'b0, 7'd10}; end			//+25, +10     #40 begin Data_A = {1'b1, 7'd25}; Data_B = {1'b1, 7'd10}; end		// -25, -10	    #80 begin Data_A = {1'b1, 7'd25}; Data_B = {1'b0, 7'd10}; end		// -25, +10    #120 begin Data_A = {1'b0, 7'd25}; Data_B = {1'b1, 7'd10}; end		// 25, -10										//  B        A    #160 begin Data_B = {1'b0, 7'd25}; Data_A = {1'b0, 7'd10}; end		//+25, +10    #200 begin Data_B = {1'b1, 7'd25}; Data_A = {1'b1, 7'd10}; end		// -25, -10    #240 begin Data_B = {1'b1, 7'd25}; Data_A = {1'b0, 7'd10}; end		// -25, +10	      #280 begin Data_B = {1'b0, 7'd25}; Data_A = {1'b1, 7'd10}; end		// +25, -10    // Addition of matching numbers    #320 begin Data_A = {1'b1,7'd0}; Data_B = {1'b1,7'd0}; end			// -0, -0     #360 begin Data_A = {1'b0,7'd0}; Data_B = {1'b0,7'd0}; end			// +0, +0     #400 begin Data_A = {1'b0,7'd0}; Data_B = {1'b1,7'd0}; end			// +0, -0     #440 begin Data_A = {1'b1,7'd0}; Data_B = {1'b0,7'd0}; end			// -0, +0     #480 begin Data_B = {1'b0, 7'd25}; Data_A = {1'b0, 7'd25}; end		// matching +    #520 begin Data_B = {1'b1, 7'd25}; Data_A = {1'b1, 7'd25}; end		// matching Ð    // Test of carry (negative numbers)    #560 begin Data_A = 8'hf0; Data_B = 8'hf0; end						// carry - -    // Test of carry (positive numbers)    #600 begin Data_A = 8'h70; Data_B = 8'h70; end	 					// carry ++  joinendmodule